from collections import Counter
import itertools


def task_func(d):
    """Count occurrences of each integer across all list values in dict d."""
    all_values = itertools.chain.from_iterable(d.values())
    return dict(Counter(all_values))


if __name__ == "__main__":
    example = {"a": [1, 2, 3], "b": [2, 3, 4], "c": [3, 4, 5]}
    print(task_func(example))  # {1: 1, 2: 2, 3: 3, 4: 2, 5: 1}
```

The function chains all the lists from the dictionary's values into a single iterable, counts each integer with `Counter`, and returns the result as a plain dictionary.
